  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  background: var(--clr-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  z-index: 100;
  text-decoration: none;
}
.skip-link:focus {
  top: 1rem;
}

/* ── Page layout ── */
.page-header {
  text-align: center;
  margin-bottom: 3rem;
}

.page-header h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a99bfa 0%, #7c6af7 50%, #5a9ef5 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.5rem;
}

.page-header p {
  color: var(--clr-muted);
  font-size: 1.05rem;
}

/* ── FAQ container ── */
.faq-list {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Individual item ── */
.example {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--clr-accent-dim);
  box-shadow: 0 0 0 1px var(--clr-accent-dim), 0 4px 20px rgba(124, 106, 247, 0.15);
}

/* ── Trigger button ── */
.faq-trigger {
  all: unset;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--clr-text);
  cursor: pointer;
  background: transparent;
  border-radius: var(--radius) var(--radius) 0 0;
  transition: background var(--transition), color var(--transition);
}

.faq-trigger:hover {
  background: var(--clr-surface-2);
  color: #fff;
}

.faq-trigger:focus-visible {
  outline: 2px solid var(--clr-focus-ring);
  outline-offset: -2px;
  border-radius: var(--radius);
}

/* Chevron icon */
.faq-trigger .icon {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  color: var(--clr-accent);
  transition: transform var(--transition);
}

.faq-trigger[aria-expanded="true"] .icon {
  transform: rotate(180deg);
}

/* ── Answer panel ── */
.details {
  overflow: hidden;
  /* JS-driven height animation */
  max-height: 0;
  transition: max-height 280ms ease;
}

.details[data-open="true"] {
  max-height: var(--panel-height, 600px);
}

.details-inner {
  padding: 0 1.25rem 1.25rem;
  color: var(--clr-muted);
  font-size: 0.975rem;
  line-height: 1.75;
  border-top: 1px solid var(--clr-border);
  padding-top: 1rem;
}

.details-inner a {
  color: var(--clr-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.details-inner a:focus-visible {
  outline: 2px solid var(--clr-focus-ring);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Responsive reflow ── */
@media (max-width: 480px) {
  .faq-trigger {
    padding: 1rem;
    font-size: 0.95rem;
  }
  .details-inner {
    padding: 0.85rem 1rem 1rem;
    font-size: 0.9rem;
  }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .example {
    border: 1px solid ButtonBorder;
  }
  .faq-trigger {
    color: ButtonText;
    forced-color-adjust: none;
    background: ButtonFace;
  }
  .faq-trigger:hover,
  .faq-trigger:focus-visible {
    background: Highlight;
    color: HighlightText;
  }
  .faq-trigger .icon {
    color: ButtonText;
  }
  .details-inner {
    color: CanvasText;
    border-top: 1px solid ButtonBorder;
  }
}
