    trigger.addEventListener('click', function () {
      var isOpen = trigger.getAttribute('aria-expanded') === 'true';
      toggle(trigger, panel, !isOpen);
    });

    trigger.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') {
        toggle(trigger, panel, false);
        trigger.focus();
      }
    });
  });

  function toggle(trigger, panel, open) {
    trigger.setAttribute('aria-expanded', String(open));

    if (open) {
      /* measure natural height so the CSS transition has an end value */
      panel.style.setProperty('--panel-height', panel.scrollHeight + 'px');
